def main(user_question: str = "") -> dict:
    cfg = load_config()
    table = infer_fact_table(user_question or "", "", cfg)
    rules = build_query_rules(table, config=cfg)
    join_list = ",".join(list_join_tables(table, cfg))
    return {
        "query_rules": rules,
        "fact_table": table,
        "join_tables": join_list,
    }
